export function loadRescueScene(spec,{readBytes,readDoors,signal}={}){return createRescueSelectedMaterial({spec,readDoors,readBytes:p=>readBytes(p,{signal}),decodeArt:b=>createImageBitmap(new Blob([b],{type:'image/png'})),decodeMask:async b=>{const image=await createImageBitmap(new Blob([b],{type:'image/png'}));try{const c=document.createElement('canvas');c.width=image.width;c.height=image.height;const g=c.getContext('2d',{willReadFrequently:true});g.drawImage(image,0,0);return{width:c.width,height:c.height,data:g.getImageData(0,0,c.width,c.height).data}}finally{image.close()}}})}
